(()=>{
  const $=id=>document.getElementById(id);
  const state={queue:[],selected:null,detail:null,token:''};
  const splitLines=value=>String(value||'').split(/\r?\n/).map(item=>item.trim()).filter(Boolean);
  const text=value=>String(value==null?'':value);
  const cleanLabel=value=>text(value).replace(/[-_]/g,' ').replace(/\b\w/g,char=>char.toUpperCase());
  const formatDate=value=>{if(!value)return'Not recorded';const date=new Date(value);return Number.isFinite(date.getTime())?date.toLocaleString():text(value);};
  const daysOverdue=value=>{const due=new Date(value).getTime();if(!Number.isFinite(due))return'';const days=Math.floor((Date.now()-due)/86400000);return days>0?`${days} day${days===1?'':'s'} overdue`:days===0?'Due today':`Due in ${Math.abs(days)} day${Math.abs(days)===1?'':'s'}`;};
  const safeRoute=value=>{const route=text(value).trim();if(!route)return'/evidence-vault.html';if(/^https?:\/\//i.test(route))return route;return route.startsWith('/')?route:`/${route}`;};
  const message=(name,value,isError=false)=>{const node=document.querySelector(`[data-message="${name}"]`);if(!node)return;node.textContent=value||'';node.style.color=isError?'#ffb09f':'#b9e6bd';};
  const adminHeaders=()=>{const token=state.token||$('admin-token')?.value.trim()||'';state.token=token;return {'Content-Type':'application/json','x-admin-token':token};};
  async function api(url,options={}){const response=await fetch(url,{cache:'no-store',headers:{Accept:'application/json',...(options.headers||{})},...options});let data={};try{data=await response.json();}catch{}if(!response.ok)throw new Error(data.error||`Request failed with ${response.status}`);return data;}
  function setLink(id,href){const node=$(id);if(!node)return;node.href=href||'#';node.hidden=!href;}
  function statusPill(label,value,klass=''){const span=document.createElement('span');span.textContent=`${label}: ${cleanLabel(value||'unknown')}`;if(klass)span.className=klass;return span;}
  function renderQueue(){const node=$('review-queue');node.replaceChildren();$('due-count').textContent=String(state.queue.length);if(!state.queue.length){const empty=document.createElement('p');empty.className='review-empty';empty.textContent='No due checkpoints are waiting for review.';node.append(empty);return;}for(const item of state.queue){const button=document.createElement('button');button.type='button';button.className='review-item';button.dataset.contractId=item.contract_id;button.dataset.checkpointDays=String(item.days_after_action);button.setAttribute('aria-current',state.selected&&state.selected.contract_id===item.contract_id&&Number(state.selected.days_after_action)===Number(item.days_after_action)?'true':'false');const title=document.createElement('strong');title.textContent=item.title||item.contract_id;const checkpoint=document.createElement('span');checkpoint.textContent=`${Number(item.days_after_action)}-day checkpoint · ${cleanLabel(item.status)}`;const due=document.createElement('small');due.textContent=`${formatDate(item.due_at)} · ${daysOverdue(item.due_at)}`;const question=document.createElement('small');question.textContent=item.review_question||'Review the documented outcome against the locked terms.';button.append(title,checkpoint,due,question);button.addEventListener('click',()=>selectItem(item));node.append(button);}}
  function evidenceChoices(items){const node=$('assessment-evidence');node.replaceChildren();if(!items.length){const empty=document.createElement('p');empty.className='muted';empty.textContent='No accepted evidence exists for this checkpoint yet.';node.append(empty);return;}for(const item of items){const label=document.createElement('label');const input=document.createElement('input');input.type='checkbox';input.name='evidenceIds';input.value=item.id;const title=document.createElement('strong');title.textContent=`${cleanLabel(item.evidence_class)} — ${item.title}`;const limits=document.createElement('small');limits.textContent=`Establishes: ${item.establishes} | Does not establish: ${item.does_not_establish}`;label.append(input,title,limits);node.append(label);}}
  function populateTerms(terms){const form=$('terms-form');if(!form)return;form.elements.responsibleActor.value=terms?.responsible_actor||'';form.elements.authorityBasis.value=terms?.authority_basis||'';form.elements.statedRationale.value=terms?.stated_rationale||'';form.elements.claimedPublicBenefit.value=terms?.claimed_public_benefit||'';try{form.elements.measurableSuccess.value=(JSON.parse(terms?.measurable_success_json||'[]')||[]).join('\n');}catch{form.elements.measurableSuccess.value='';}try{form.elements.primarySourceUrls.value=(JSON.parse(terms?.primary_source_urls_json||'[]')||[]).join('\n');}catch{form.elements.primarySourceUrls.value='';}form.elements.reviewedBy.value=terms?.locked_by||'';}
  function renderWorkspace(item,detail){state.selected=item;state.detail=detail;$('review-empty').hidden=true;$('review-workspace').hidden=false;$('workspace-title').textContent=item.title||detail.contract?.title||item.contract_id;$('workspace-lane').textContent=`${Number(item.days_after_action)}-DAY ACCOUNTABILITY REVIEW`;$('workspace-question').textContent=item.review_question||detail.contract?.accountability_question||'Review the documented outcome against the original decision terms.';$('workspace-due').textContent=`Due ${formatDate(item.due_at)}. ${daysOverdue(item.due_at)}.`;$('workspace-state').textContent=`Checkpoint: ${cleanLabel(item.status)}. Terms: ${cleanLabel(detail.contract?.terms_lock)}. Current public verdict: ${cleanLabel(detail.contract?.outcome_verdict)}.`;$('workspace-boundary').textContent=detail.contract?.evidence_boundary||'A due review is not a finding. Conclusions require primary terms, accepted evidence, counter-evidence and editorial review.';const status=$('workspace-status');status.replaceChildren(statusPill('Checkpoint',item.status,'due'),statusPill('Terms',detail.contract?.terms_lock,detail.contract?.terms_lock==='locked-primary-decision-record'?'ready':''),statusPill('Outcome',detail.contract?.outcome_verdict));setLink('workspace-public',safeRoute(detail.contract?.route||`/public-consequence-contracts.html#${item.contract_id}`));setLink('workspace-source',detail.contract?.source_url||'');setLink('workspace-evidence',safeRoute(item.evidence_route||detail.contract?.evidence_route));populateTerms(detail.terms);const accepted=(detail.evidence||[]).filter(entry=>Number(entry.checkpoint_days)===Number(item.days_after_action)&&entry.review_status==='accepted');evidenceChoices(accepted);renderQueue();}
  async function selectItem(item){try{const detail=await api(`/api/public/consequence-contracts/${encodeURIComponent(item.contract_id)}`);renderWorkspace(item,detail);}catch(error){alert(error.message||'Unable to open review item.');}}
  async function loadQueue(){const node=$('review-queue');node.innerHTML='<p class="review-empty">Loading due checkpoints…</p>';try{const data=await api('/api/public/consequence-due');state.queue=data.items||[];renderQueue();if(state.selected){const replacement=state.queue.find(item=>item.contract_id===state.selected.contract_id&&Number(item.days_after_action)===Number(state.selected.days_after_action));if(replacement)await selectItem(replacement);else{$('review-workspace').hidden=true;$('review-empty').hidden=false;state.selected=null;state.detail=null;}}}catch(error){node.innerHTML='';const failed=document.createElement('p');failed.className='review-empty';failed.textContent=error.message||'Review inbox unavailable.';node.append(failed);}}
  async function submitJson(url,payload,name){if(!state.token&&!$('admin-token').value.trim())throw new Error('Enter the administrator token first.');message(name,'Submitting…');const data=await api(url,{method:'POST',headers:adminHeaders(),body:JSON.stringify(payload)});message(name,'Saved successfully.');return data;}
  $('terms-form')?.addEventListener('submit',async event=>{event.preventDefault();if(!state.selected)return message('terms','Select a checkpoint first.',true);const form=new FormData(event.currentTarget);try{await submitJson('/api/admin/consequence-contracts/lock',{contractId:state.selected.contract_id,responsibleActor:form.get('responsibleActor'),authorityBasis:form.get('authorityBasis'),statedRationale:form.get('statedRationale'),claimedPublicBenefit:form.get('claimedPublicBenefit'),measurableSuccess:splitLines(form.get('measurableSuccess')),primarySourceUrls:splitLines(form.get('primarySourceUrls')),reviewedBy:form.get('reviewedBy')},'terms');await selectItem(state.selected);}catch(error){message('terms',error.message,true);}});
  $('evidence-form')?.addEventListener('submit',async event=>{event.preventDefault();if(!state.selected)return message('evidence','Select a checkpoint first.',true);const form=new FormData(event.currentTarget);try{await submitJson('/api/admin/consequence-evidence',{contractId:state.selected.contract_id,checkpointDays:Number(state.selected.days_after_action),evidenceClass:form.get('evidenceClass'),title:form.get('title'),sourceUrl:form.get('sourceUrl'),publishedAt:form.get('publishedAt'),establishes:form.get('establishes'),doesNotEstablish:form.get('doesNotEstablish'),evidenceRoute:form.get('evidenceRoute'),submittedBy:form.get('submittedBy')},'evidence');event.currentTarget.elements.title.value='';event.currentTarget.elements.sourceUrl.value='';event.currentTarget.elements.publishedAt.value='';event.currentTarget.elements.establishes.value='';event.currentTarget.elements.doesNotEstablish.value='';await selectItem(state.selected);}catch(error){message('evidence',error.message,true);}});
  $('assessment-form')?.addEventListener('submit',async event=>{event.preventDefault();if(!state.selected)return message('assessment','Select a checkpoint first.',true);const form=new FormData(event.currentTarget);const evidenceIds=[...event.currentTarget.querySelectorAll('input[name="evidenceIds"]:checked')].map(input=>input.value);try{const result=await submitJson('/api/admin/consequence-assessment',{contractId:state.selected.contract_id,checkpointDays:Number(state.selected.days_after_action),overallFinding:form.get('overallFinding'),implementationStatus:form.get('implementationStatus'),publicBenefitStatus:form.get('publicBenefitStatus'),moneyBeneficiaryStatus:form.get('moneyBeneficiaryStatus'),affectedGroupsStatus:form.get('affectedGroupsStatus'),confidence:Number(form.get('confidence')),summary:form.get('summary'),alternativeExplanations:splitLines(form.get('alternativeExplanations')),falsifiersTested:splitLines(form.get('falsifiersTested')),evidenceIds,evidenceRoute:form.get('evidenceRoute'),publicationStatus:form.get('publicationStatus'),reviewedBy:form.get('reviewedBy')},'assessment');message('assessment',result.publicationStatus==='published'?'Reviewed outcome published.':'Draft saved for editorial review.');await loadQueue();}catch(error){message('assessment',error.message,true);}});
  $('refresh-inbox')?.addEventListener('click',loadQueue);
  $('clear-token')?.addEventListener('click',()=>{state.token='';$('admin-token').value='';message('terms','Administrator token cleared from browser memory.');});
  $('admin-token')?.addEventListener('input',event=>{state.token=event.target.value.trim();});
  loadQueue();
})();
